formula:
ma5:MA(CLOSE,5),COLORWHITE,LINETHICK2;
ma13:MA(CLOSE,13),COLORGREEN;
ma21:MA(CLOSE,21),COLORYELLOW,LINETHICK2;
ma34:MA(CLOSE,34),COLORMAGENTA;
angel:=EMA(CLOSE,2);
devil:=EMA(CLOSE+20*SLOPE(CLOSE,21),42);
bull:IF(ISVALID(angel) AND ISVALID(devil),angel>=devil,DRAWNULL),NODRAW;
attack:=CROSS(angel,devil); retreat:=CROSS(devil,angel);
DRAWICON(attack,LOW*0.97,1,5),COLORRED;
DRAWTEXT(attack,LOW*0.92,'进攻'),COLORYELLOW;
DRAWICON(retreat,HIGH*1.03,2,5),COLORCYAN;
DRAWTEXT(retreat,HIGH*1.08,'撤退'),COLORWHITE;
